// Arduino Bench — Unit 5: See contact bounce (and a floating pin)
//
// Button between D2 and GND (internal pull-up enabled).
// An interrupt counts EVERY edge on D2, so you can see how many times one
// "click" really toggles the pin.
//
// Send 'f' to toggle the floating-pin monitor on D7 (leave a loose jumper
// wire plugged into D7 and nothing else - then touch it / wave your hand).

const byte BUTTON_PIN = 2;
const byte FLOAT_PIN = 7;

volatile unsigned int edges = 0;
volatile unsigned long firstEdgeUs = 0;
volatile unsigned long lastEdgeUs = 0;

bool floatMonitor = false;

void onEdge() {
  unsigned long now = micros();
  if (edges == 0) firstEdgeUs = now;
  lastEdgeUs = now;
  edges++;
}

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(FLOAT_PIN, INPUT);  // deliberately NO pull-up: it floats
  attachInterrupt(digitalPinToInterrupt(BUTTON_PIN), onEdge, CHANGE);
  Serial.println(F("Press and release the button. 'f' = floating-pin monitor."));
}

void loop() {
  if (Serial.available() && Serial.read() == 'f') {
    floatMonitor = !floatMonitor;
  }

  if (floatMonitor) {
    Serial.print(F("D7_floating:"));
    Serial.println(digitalRead(FLOAT_PIN));
    delay(20);
    return;
  }

  // Report once the line has been quiet for 50 ms
  noInterrupts();
  unsigned int n = edges;
  unsigned long first = firstEdgeUs, last = lastEdgeUs;
  interrupts();

  if (n > 0 && micros() - last > 50000UL) {
    Serial.print(F("Edges: "));
    Serial.print(n);
    Serial.print(F("  (ideal press+release = 2)  burst length: "));
    Serial.print(last - first);
    Serial.println(F(" us"));
    noInterrupts();
    edges = 0;
    interrupts();
  }
}

// Arduino Bench — Unit 5: Interrupt-timed Reaction Tester
//
// LED (with 220 ohm) on D8, button D2 -> GND, passive buzzer on D10 (optional).
// Wait for the LED, then hit the button. The press time is captured INSIDE
// the interrupt with micros(), so the measurement doesn't depend on how
// busy loop() is.

const byte BUTTON_PIN = 2;
const byte LED_PIN = 8;
const byte BUZZER_PIN = 10;

enum State { READY, WAITING, GO, SHOW };
State state = READY;

volatile bool pressed = false;
volatile unsigned long pressUs = 0;
volatile unsigned long lastIsrUs = 0;

unsigned long goUs = 0;
unsigned long waitUntilMs = 0;
unsigned long bestUs = 0xFFFFFFFFUL;
unsigned long stateStartMs = 0;

void onPress() {
  unsigned long now = micros();
  if (now - lastIsrUs < 150000UL) return;  // software debounce: ignore bounces
  lastIsrUs = now;
  pressUs = now;
  pressed = true;
}

// A press only counts if the button is STILL held 10 ms after the edge.
// Releasing the button also bounces and makes falling edges - those read
// HIGH again 10 ms later, so they get rejected here.
bool takePress() {
  noInterrupts();
  bool p = pressed;
  unsigned long t = pressUs;
  interrupts();
  if (!p) return false;
  if (micros() - t < 10000UL) return false;  // too soon to judge, ask again later
  noInterrupts();
  pressed = false;
  interrupts();
  return digitalRead(BUTTON_PIN) == LOW;
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(BUTTON_PIN), onPress, FALLING);
  randomSeed(analogRead(A5) ^ micros());  // floating pin noise as a seed
  Serial.println(F("Reaction tester. Press the button to start a round."));
}

void loop() {
  switch (state) {
    case READY:
      if (takePress()) {
        Serial.println(F("Get ready... wait for the light!"));
        waitUntilMs = millis() + random(2000, 5000);
        state = WAITING;
      }
      break;

    case WAITING:
      if (takePress()) {
        Serial.println(F("Too early! Press to try again."));
        tone(BUZZER_PIN, 150, 400);
        state = READY;
      } else if ((long)(millis() - waitUntilMs) >= 0) {
        digitalWrite(LED_PIN, HIGH);
        goUs = micros();
        state = GO;
      }
      break;

    case GO:
      if (takePress()) {
        digitalWrite(LED_PIN, LOW);
        unsigned long r = pressUs - goUs;
        Serial.print(F("Reaction: "));
        Serial.print(r / 1000.0, 1);
        Serial.print(F(" ms"));
        if (r < bestUs) {
          bestUs = r;
          Serial.print(F("  NEW BEST!"));
          tone(BUZZER_PIN, 1760, 150);
        }
        Serial.print(F("   best: "));
        Serial.print(bestUs / 1000.0, 1);
        Serial.println(F(" ms. Press for another round."));
        stateStartMs = millis();
        state = SHOW;
      }
      break;

    case SHOW:
      if (millis() - stateStartMs > 300) {
        takePress();  // drop any press that happened while showing
        state = READY;
      }
      break;
  }
}

