// Arduino Bench — Unit 6: 74HC595 shift register — 8 outputs from 3 pins
//
// 74HC595   Arduino
//   14 DS    -> D11 (data)
//   11 SHCP  -> D12 (shift clock)
//   12 STCP  -> D8  (latch / storage clock)
//   13 /OE   -> D9  (PWM: brightness, active LOW!)
//   10 /MR   -> 5V  (never reset)
//   16 VCC   -> 5V,  8 GND -> GND,  100 nF cap between 16 and 8
//   Q0..Q7 (15, 1..7) -> 1k resistor -> LED -> GND
//
// Serial: 0..9 = brightness, m = next pattern

const byte DATA_PIN = 11;
const byte CLOCK_PIN = 12;
const byte LATCH_PIN = 8;
const byte OE_PIN = 9;

byte pattern = 0;  // 0 binary counter, 1 scanner, 2 sparkle
unsigned long lastFrame = 0;
byte counter = 0;
int scanPos = 0, scanDir = 1;

void writeOutputs(byte value) {
  digitalWrite(LATCH_PIN, LOW);                  // outputs keep their old value...
  shiftOut(DATA_PIN, CLOCK_PIN, MSBFIRST, value); // ...while 8 new bits shift in
  digitalWrite(LATCH_PIN, HIGH);                 // rising edge copies them to Q0..Q7
}

void setBrightness(byte level) {          // level 0..9
  analogWrite(OE_PIN, 255 - level * 255 / 9);  // /OE is active LOW -> invert
}

void setup() {
  Serial.begin(115200);
  pinMode(DATA_PIN, OUTPUT);
  pinMode(CLOCK_PIN, OUTPUT);
  pinMode(LATCH_PIN, OUTPUT);
  pinMode(OE_PIN, OUTPUT);
  setBrightness(9);
  writeOutputs(0);
  Serial.println(F("0-9 brightness, m = next pattern"));
}

void loop() {
  if (Serial.available()) {
    char c = Serial.read();
    if (c >= '0' && c <= '9') setBrightness(c - '0');
    if (c == 'm') { pattern = (pattern + 1) % 3; Serial.print(F("pattern ")); Serial.println(pattern); }
  }

  if (millis() - lastFrame < 120) return;
  lastFrame = millis();

  switch (pattern) {
    case 0:  // binary counter: watch Q0 toggle every frame, Q7 every 128 frames
      writeOutputs(counter++);
      break;
    case 1:  // scanner
      writeOutputs(1 << scanPos);
      scanPos += scanDir;
      if (scanPos == 7 || scanPos == 0) scanDir = -scanDir;
      break;
    case 2:  // sparkle
      writeOutputs(random(256) & random(256));
      break;
  }
}

// Arduino Bench — Unit 6: 7-segment Electronic Die (via 74HC595)
//
// Same 595 wiring as the counter lab, but Q0..Q7 drive segments a..g + dp
// of a COMMON-CATHODE 7-segment display (common pins -> GND), each segment
// through its own 1k resistor. Button D2 -> GND.
//
// Bit 0 of each byte = segment a, bit 6 = g, bit 7 = decimal point.
//      a
//     ---
//  f |   | b
//     -g-
//  e |   | c
//     ---  . dp
//      d

const byte DATA_PIN = 11;
const byte CLOCK_PIN = 12;
const byte LATCH_PIN = 8;
const byte OE_PIN = 9;
const byte BUTTON_PIN = 2;

const byte DIGITS[10] = {
  0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
};
const byte DP = 0x80;

void show(byte segments) {
  digitalWrite(LATCH_PIN, LOW);
  shiftOut(DATA_PIN, CLOCK_PIN, MSBFIRST, segments);
  digitalWrite(LATCH_PIN, HIGH);
}

void roll() {
  // Spin fast, then slow down like a real die
  int delayMs = 30;
  byte face = 1;
  while (delayMs < 300) {
    face = random(1, 7);
    show(DIGITS[face] | DP);
    delay(delayMs);
    delayMs = delayMs * 23 / 20;  // +15 % each step
  }
  show(DIGITS[face]);
  Serial.print(F("Rolled: "));
  Serial.println(face);
}

void setup() {
  Serial.begin(115200);
  pinMode(DATA_PIN, OUTPUT);
  pinMode(CLOCK_PIN, OUTPUT);
  pinMode(LATCH_PIN, OUTPUT);
  pinMode(OE_PIN, OUTPUT);
  digitalWrite(OE_PIN, LOW);  // outputs on
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  show(0x40);                 // just segment g: "-"
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    // The exact microsecond you press is unpredictable -> good randomness
    randomSeed(micros() ^ analogRead(A5));
    roll();
    while (digitalRead(BUTTON_PIN) == LOW) {}  // wait for release
    delay(30);                                   // ignore release bounce
  }
}

// Arduino Bench — Unit 7: NTC Thermistor Thermometer (Beta equation)
//
// 5V --[R_FIXED 10k]--+-- A0
//                     |
//                   [NTC 10k]
//                     |
//                    GND
//
// Ratiometric: V(A0)/Vcc = R_ntc / (R_fixed + R_ntc), so the supply voltage
// cancels out:  R_ntc = R_fixed * adc / (1024 - adc)
//
// Beta equation:  1/T = 1/T0 + (1/B) * ln(R/R0)      (T in kelvin)

const float R_FIXED = 10000.0;  // measure it!
const float R0 = 10000.0;       // thermistor resistance at T0
const float T0_K = 298.15;      // 25 C
float BETA = 3950.0;            // typical for kit thermistors - calibrate in the lab!
const float ALPHA = 0.1;        // smoothing factor for the exponential filter

float smoothC = NAN;

void setup() {
  Serial.begin(115200);
  Serial.println(F("Thermistor. Type a Beta value (e.g. 3435) + Enter to change it."));
}

void loop() {
  if (Serial.available()) {
    float b = Serial.parseFloat();
    if (b > 1000 && b < 6000) BETA = b;
  }

  long sum = 0;
  for (byte i = 0; i < 16; i++) sum += analogRead(A0);
  float adc = sum / 16.0;
  if (adc < 1 || adc > 1022) {
    Serial.println(F("Out of range - check wiring"));
    delay(500);
    return;
  }

  float r = R_FIXED * adc / (1024.0 - adc);
  float tK = 1.0 / (1.0 / T0_K + log(r / R0) / BETA);
  float tC = tK - 273.15;

  if (isnan(smoothC)) smoothC = tC;
  smoothC += ALPHA * (tC - smoothC);  // exponential moving average

  Serial.print(F("R_ntc_ohm:"));
  Serial.print(r, 0);
  Serial.print(F(" raw_C:"));
  Serial.print(tC, 2);
  Serial.print(F(" smooth_C:"));
  Serial.print(smoothC, 2);
  Serial.print(F(" beta:"));
  Serial.println(BETA, 0);
  delay(250);
}

// Arduino Bench — Unit 7: Night light with HYSTERESIS
//
// 5V --[LDR]--+-- A0          (more light -> higher reading)
//             |
//          [10k]
//             |
//            GND
// D9 --[220]-- LED -- GND
//
// Two thresholds instead of one: turn ON below ON_BELOW, turn OFF above
// OFF_ABOVE. The gap between them is the hysteresis band.
// Send 'h' to switch hysteresis off/on and count how often the LED toggles
// when you hold your hand so the light level sits right at the edge.

const byte LDR_PIN = A0;
const byte LED_PIN = 9;

int ON_BELOW = 300;
int OFF_ABOVE = 400;
bool hysteresis = true;
bool lightOn = false;

unsigned int toggles = 0;
unsigned long windowStart = 0;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  if (Serial.available() && Serial.read() == 'h') {
    hysteresis = !hysteresis;
    toggles = 0;
    windowStart = millis();
  }

  int level = analogRead(LDR_PIN);
  bool newState = lightOn;
  if (hysteresis) {
    if (level < ON_BELOW) newState = true;
    if (level > OFF_ABOVE) newState = false;
  } else {
    int single = (ON_BELOW + OFF_ABOVE) / 2;
    newState = level < single;
  }

  if (newState != lightOn) {
    lightOn = newState;
    toggles++;
  }
  digitalWrite(LED_PIN, lightOn);

  if (millis() - windowStart > 10000) {
    windowStart = millis();
    toggles = 0;
  }

  Serial.print(F("light:"));
  Serial.print(level);
  Serial.print(F(" on_below:"));
  Serial.print(hysteresis ? ON_BELOW : (ON_BELOW + OFF_ABOVE) / 2);
  Serial.print(F(" off_above:"));
  Serial.print(hysteresis ? OFF_ABOVE : (ON_BELOW + OFF_ABOVE) / 2);
  Serial.print(F(" led_x100:"));
  Serial.print(lightOn ? 100 : 0);
  Serial.print(F(" toggles_10s:"));
  Serial.println(toggles);
  delay(10);
}

