// Arduino Bench — Unit 8: Sonar Rangefinder + Theremin
//
// HC-SR04: VCC->5V, GND->GND, TRIG->D7, ECHO->D6
// Passive buzzer: D8 -> buzzer -> GND (add 100 ohm in series to make it quieter)
// Optional: the Unit 7 thermistor divider on A0 for speed-of-sound correction.
//
// distance = (echo time * speed of sound) / 2      (there AND back)
// speed of sound ~= 331.3 + 0.606 * T(C)  m/s
//
// Serial: 'm' toggles mute, 'p' toggles pentatonic (musical) vs smooth pitch.

const byte TRIG_PIN = 7;
const byte ECHO_PIN = 6;
const byte BUZZER_PIN = 8;
const bool USE_THERMISTOR = false;  // set true if the Unit 7 divider is on A0
float airTempC = 20.0;

bool muted = false;
bool pentatonic = true;

// C major pentatonic, two octaves (Hz)
const int SCALE[] = {262, 294, 330, 392, 440, 523, 587, 659, 784, 880};
const byte SCALE_LEN = sizeof(SCALE) / sizeof(SCALE[0]);

float readThermistorC() {
  float adc = analogRead(A0);
  if (adc < 1 || adc > 1022) return airTempC;
  float r = 10000.0 * adc / (1024.0 - adc);
  float tK = 1.0 / (1.0 / 298.15 + log(r / 10000.0) / 3950.0);
  return tK - 273.15;
}

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);   // 10 us pulse starts a "ping" (8 cycles of 40 kHz)
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long us = pulseIn(ECHO_PIN, HIGH, 30000UL);  // 30 ms ~ 5 m round trip
  if (us == 0) return -1;         // no echo
  float c = 331.3 + 0.606 * airTempC;          // m/s
  return us * (c / 10000.0) / 2.0;             // us * cm/us / 2
}

void setup() {
  Serial.begin(115200);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  Serial.println(F("Sonar theremin. m = mute, p = pentatonic/smooth"));
}

void loop() {
  if (Serial.available()) {
    char ch = Serial.read();
    if (ch == 'm') muted = !muted;
    if (ch == 'p') pentatonic = !pentatonic;
  }
  if (USE_THERMISTOR) airTempC = readThermistorC();

  float d = readDistanceCm();

  Serial.print(F("distance_cm:"));
  Serial.print(d, 1);
  Serial.print(F(" air_C:"));
  Serial.println(airTempC, 1);

  if (muted || d < 5 || d > 50) {
    noTone(BUZZER_PIN);
  } else if (pentatonic) {
    byte i = constrain((int)((d - 5) / 45.0 * SCALE_LEN), 0, SCALE_LEN - 1);
    tone(BUZZER_PIN, SCALE[SCALE_LEN - 1 - i]);  // closer hand = higher note
  } else {
    tone(BUZZER_PIN, map((long)d, 5, 50, 1500, 200));
  }
  delay(60);  // let echoes die out before the next ping (datasheet: >= 60 ms)
}

// Arduino Bench — Unit 9: Watch the 555's timing capacitor
//
// Connect the 555's pin 6/2 node (top of the timing capacitor) to A0.
// Use the SLOW version of the circuit (C = 10 uF, ~7 Hz) so the ADC can
// keep up. Common ground between the 555 and the Arduino!
//
// Serial Plotter shows the capacitor voltage bouncing between the 555's two
// comparator thresholds: 1/3 Vcc and 2/3 Vcc.
// Send 'm' to switch between plotting and a min / max / frequency report.

const float VCC = 5.00;
bool statsMode = false;

void setup() {
  Serial.begin(115200);
}

void plotOnce() {
  float v = analogRead(A0) * VCC / 1024.0;
  Serial.print(F("cap_V:"));
  Serial.print(v, 3);
  Serial.print(F(" one_third:"));
  Serial.print(VCC / 3.0, 3);
  Serial.print(F(" two_thirds:"));
  Serial.println(VCC * 2.0 / 3.0, 3);
  delay(4);
}

void statsOnce() {
  // Sample for 2 seconds, track min/max and count upward crossings of 2.5 V
  int lo = 1023, hi = 0, crossings = 0;
  bool above = analogRead(A0) > 512;
  unsigned long t0 = millis(), firstCross = 0, lastCross = 0;
  while (millis() - t0 < 2000) {
    int a = analogRead(A0);
    lo = min(lo, a);
    hi = max(hi, a);
    if (!above && a > 522) {           // 10-count hysteresis around 512
      above = true;
      lastCross = millis();
      if (crossings == 0) firstCross = lastCross;
      crossings++;
    } else if (above && a < 502) {
      above = false;
    }
  }
  Serial.print(F("min "));
  Serial.print(lo * VCC / 1024.0, 3);
  Serial.print(F(" V   max "));
  Serial.print(hi * VCC / 1024.0, 3);
  Serial.print(F(" V   f = "));
  if (crossings >= 2) {
    Serial.print(1000.0 * (crossings - 1) / (lastCross - firstCross), 2);
    Serial.println(F(" Hz"));
  } else {
    Serial.println(F("? (too slow / not oscillating)"));
  }
}

void loop() {
  if (Serial.available() && Serial.read() == 'm') statsMode = !statsMode;
  if (statsMode) statsOnce();
  else plotOnce();
}

// Arduino Bench — Unit 9: Frequency counter (two methods)
//
// Signal (0..5 V only!) -> D2.  Common ground.
//
// Method A — period measurement: time one HIGH and one LOW with pulseIn().
//            Great resolution for slow signals, also gives duty cycle.
// Method B — gate counting: count rising edges for exactly 1 s.
//            Resolution is +-1 count = +-1 Hz, so it shines on FAST signals.

const byte SIGNAL_PIN = 2;
volatile unsigned long edgeCount = 0;

void onRise() { edgeCount++; }

void setup() {
  Serial.begin(115200);
  pinMode(SIGNAL_PIN, INPUT);
  Serial.println(F("Frequency counter on D2"));
}

void loop() {
  // --- Method A: period ---
  unsigned long hi = pulseIn(SIGNAL_PIN, HIGH, 1000000UL);
  unsigned long lo = pulseIn(SIGNAL_PIN, LOW, 1000000UL);

  // --- Method B: 1-second gate ---
  noInterrupts();
  edgeCount = 0;
  interrupts();
  attachInterrupt(digitalPinToInterrupt(SIGNAL_PIN), onRise, RISING);
  delay(1000);
  detachInterrupt(digitalPinToInterrupt(SIGNAL_PIN));
  noInterrupts();
  unsigned long counted = edgeCount;
  interrupts();

  Serial.print(F("A) period: high "));
  Serial.print(hi);
  Serial.print(F(" us, low "));
  Serial.print(lo);
  Serial.print(F(" us"));
  if (hi > 0 && lo > 0) {
    float period = hi + lo;
    Serial.print(F(" -> f = "));
    Serial.print(1e6 / period, 2);
    Serial.print(F(" Hz, duty = "));
    Serial.print(100.0 * hi / period, 1);
    Serial.print(F(" %"));
  } else {
    Serial.print(F(" (no signal)"));
  }
  Serial.print(F("   |   B) gate: "));
  Serial.print(counted);
  Serial.println(F(" Hz"));
}

