// Arduino Bench — Unit 10: H-bridge motor control (L293D)
//
// L293D   Arduino / power
//   1 EN1,2 -> D5 (PWM)         16 VCC1 (logic) -> 5V
//   2 1A    -> D4               8  VCC2 (motor) -> separate motor supply (+)
//   7 2A    -> D3               4,5,12,13 GND   -> common GND
//   3 1Y    -> motor lead A
//   6 2Y    -> motor lead B
// Pot on A0: centre = stop, right = forward, left = reverse.
// Serial: 'b' toggles stop mode between BRAKE (short the motor) and COAST (float).

const byte EN_PIN = 5;
const byte IN1_PIN = 4;
const byte IN2_PIN = 3;
const int DEADBAND = 40;  // counts around the centre that mean "stop"

bool brakeMode = true;

void drive(int speed) {  // -255..255
  if (speed > 0) {
    digitalWrite(IN1_PIN, HIGH);
    digitalWrite(IN2_PIN, LOW);
    analogWrite(EN_PIN, speed);
  } else if (speed < 0) {
    digitalWrite(IN1_PIN, LOW);
    digitalWrite(IN2_PIN, HIGH);
    analogWrite(EN_PIN, -speed);
  } else if (brakeMode) {
    digitalWrite(IN1_PIN, LOW);   // both outputs LOW -> motor terminals shorted
    digitalWrite(IN2_PIN, LOW);   // -> back-EMF current brakes it hard
    digitalWrite(EN_PIN, HIGH);
  } else {
    digitalWrite(EN_PIN, LOW);    // outputs high-impedance -> motor coasts
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(EN_PIN, OUTPUT);
  pinMode(IN1_PIN, OUTPUT);
  pinMode(IN2_PIN, OUTPUT);
  Serial.println(F("H-bridge. Turn the pot. 'b' = brake/coast"));
}

void loop() {
  if (Serial.available() && Serial.read() == 'b') {
    brakeMode = !brakeMode;
    Serial.println(brakeMode ? F("stop = BRAKE") : F("stop = COAST"));
  }

  int offset = analogRead(A0) - 512;
  int speed = 0;
  if (offset > DEADBAND) speed = map(offset, DEADBAND, 511, 60, 255);
  else if (offset < -DEADBAND) speed = -map(-offset, DEADBAND, 512, 60, 255);
  drive(speed);

  Serial.print(F("speed:"));
  Serial.println(speed);
  delay(50);
}

// Arduino Bench — Unit 10: Sun Tracker (closed-loop proportional control)
//
// Two LDRs side by side on the servo horn, separated by a small cardboard
// "fin" so each one is shaded when the light comes from the other side.
//   5V --[LDR left]--+-- A0      5V --[LDR right]--+-- A1
//                  [10k]                         [10k]
//                    |                              |
//                   GND                            GND
// Servo: signal -> D9, red -> 5V (better: external 5V), brown -> GND.
// Put 100..470 uF across the servo's power pins.
//
// Control law:  error = left - right;   angle += KP * error
// Serial: '+'/'-' change KP,  ']'/'[' change deadband,  'x' flips direction

#include <Servo.h>

Servo servo;
float angle = 90;
float KP = 0.02;
int DEADBAND = 15;
int direction = 1;

void setup() {
  Serial.begin(115200);
  servo.attach(9);
  servo.write((int)angle);
  Serial.println(F("+/- KP, [/] deadband, x = flip direction"));
}

void loop() {
  if (Serial.available()) {
    char c = Serial.read();
    if (c == '+') KP *= 1.5;
    if (c == '-') KP /= 1.5;
    if (c == ']') DEADBAND += 5;
    if (c == '[' && DEADBAND >= 5) DEADBAND -= 5;
    if (c == 'x') direction = -direction;
  }

  int left = analogRead(A0);
  int right = analogRead(A1);
  int error = left - right;

  if (abs(error) > DEADBAND) {
    angle += direction * KP * error;
    angle = constrain(angle, 0, 180);
    servo.write((int)angle);
  }

  Serial.print(F("left:"));
  Serial.print(left);
  Serial.print(F(" right:"));
  Serial.print(right);
  Serial.print(F(" error:"));
  Serial.print(error);
  Serial.print(F(" angle_x5:"));
  Serial.print(angle * 5, 0);
  Serial.print(F(" KP_x1000:"));
  Serial.println(KP * 1000, 0);
  delay(20);
}

// Arduino Bench — Unit 10: Stepper that follows a knob (28BYJ-48 + ULN2003)
//
// ULN2003 board: IN1->D8, IN2->D9, IN3->D10, IN4->D11, + -> external 5V, - -> GND
// Pot on A0. The shaft points to wherever the knob points (open-loop:
// no sensor! the Arduino just counts the steps it has sent).

#include <Stepper.h>

const int STEPS_PER_REV = 2048;  // 32 steps x ~64:1 gearbox (full-step mode)
// Pin order IN1, IN3, IN2, IN4 gives the correct coil sequence for this motor
Stepper stepper(STEPS_PER_REV, 8, 10, 9, 11);

long position = 0;  // steps we've sent so far

void setup() {
  Serial.begin(115200);
  stepper.setSpeed(12);  // rpm; above ~15 rpm this motor starts skipping steps
}

void loop() {
  long target = map(analogRead(A0), 0, 1023, 0, STEPS_PER_REV);
  long diff = target - position;
  if (abs(diff) > 4) {                // small deadband stops jitter
    int chunk = constrain(diff, -16, 16);
    stepper.step(chunk);
    position += chunk;
  }
  static unsigned long lastPrint = 0;
  if (millis() - lastPrint > 200) {
    lastPrint = millis();
    Serial.print(F("target:"));
    Serial.print(target);
    Serial.print(F(" position:"));
    Serial.println(position);
  }
}

