// Arduino Bench — Unit 11: Optical Serial Link (build your own UART)
//
// TX:  D7 --[220]-- LED -- GND        (point the LED straight at the LDR)
// RX:  5V --[LDR]--+-- A0
//                [10k]
//                  |
//                 GND
// Shield the LED+LDR pair from room light with a paper tube or black tape.
//
// The frame is a real UART frame, sent with light:
//   idle = LIGHT (logic 1)  | start bit = DARK (0) | 8 data bits, LSB first |
//   2 stop bits = LIGHT (1)
// The receiver is independent of the transmitter: it waits for the
// light->dark edge of a start bit, jumps 1.5 bit-times ahead to land in the
// MIDDLE of data bit 0, then samples once per bit-time.
//
// Type a message in Serial Monitor (Newline ending) and press Enter.
// Type  #20  to change the speed to 20 baud. Push it until it breaks!

const byte TX_PIN = 7;
const byte RX_PIN = A0;

unsigned int baud = 10;
unsigned long bitUs = 100000UL;

int thLow, thHigh;       // hysteresis thresholds
bool lineLight = true;   // digitised RX line (true = light = 1)

// ---- TX ----
char txQueue[64];
byte qHead = 0, qTail = 0;
int txBit = -1;          // -1 idle, 0 start, 1..8 data, 9..10 stop
byte txByte;
unsigned long txNextUs;

// ---- RX ----
int rxBit = -1;          // -1 waiting for start, 0..7 data, 8 stop
byte rxByte;
unsigned long rxNextUs;
bool rxArmed = true;     // must see the line light again before a new frame
unsigned int framingErrors = 0;

// ---- typed line ----
char lineBuf[64];
byte lineLen = 0;

bool due(unsigned long t) { return (long)(micros() - t) >= 0; }

int averageLevel() {
  long s = 0;
  for (byte i = 0; i < 32; i++) { s += analogRead(RX_PIN); delay(5); }
  return s / 32;
}

void calibrate() {
  digitalWrite(TX_PIN, LOW);
  delay(600);
  int dark = averageLevel();
  digitalWrite(TX_PIN, HIGH);
  delay(600);
  int light = averageLevel();
  int span = light - dark;
  thLow = dark + span * 35 / 100;
  thHigh = dark + span * 65 / 100;
  Serial.print(F("Calibration: dark="));
  Serial.print(dark);
  Serial.print(F(" light="));
  Serial.print(light);
  Serial.print(F(" thresholds="));
  Serial.print(thLow);
  Serial.print('/');
  Serial.println(thHigh);
  if (span < 80) Serial.println(F("WARNING: weak contrast - move LED closer / shield from room light"));
}

void enqueue(char c) {
  byte next = (qHead + 1) % sizeof(txQueue);
  if (next != qTail) { txQueue[qHead] = c; qHead = next; }
}

void serviceTx() {
  if (txBit == -1) {
    if (qHead == qTail) return;             // nothing to send, stay idle (light)
    txByte = txQueue[qTail];
    qTail = (qTail + 1) % sizeof(txQueue);
    digitalWrite(TX_PIN, LOW);              // start bit: dark
    txBit = 0;
    txNextUs = micros() + bitUs;
    return;
  }
  if (!due(txNextUs)) return;
  txNextUs += bitUs;
  txBit++;
  if (txBit <= 8) {
    digitalWrite(TX_PIN, bitRead(txByte, txBit - 1) ? HIGH : LOW);  // LSB first
  } else if (txBit <= 10) {
    digitalWrite(TX_PIN, HIGH);             // stop bits: light
  } else {
    txBit = -1;                             // frame done
  }
}

void serviceRx() {
  int level = analogRead(RX_PIN);
  if (level > thHigh) lineLight = true;
  if (level < thLow) lineLight = false;

  if (rxBit == -1) {
    if (lineLight) rxArmed = true;
    if (rxArmed && !lineLight) {            // light -> dark: a start bit begins
      rxArmed = false;
      rxBit = 0;
      rxByte = 0;
      rxNextUs = micros() + bitUs + bitUs / 2;
    }
    return;
  }
  if (!due(rxNextUs)) return;
  rxNextUs += bitUs;
  if (rxBit < 8) {
    if (lineLight) bitSet(rxByte, rxBit);
    rxBit++;
  } else {                                  // stop bit must be light
    if (lineLight) {
      Serial.write(rxByte);
    } else {
      framingErrors++;
      Serial.print(F("[framing error #"));
      Serial.print(framingErrors);
      Serial.print(']');
    }
    rxBit = -1;
  }
}

void setBaud(unsigned int b) {
  baud = constrain(b, 1, 200);
  bitUs = 1000000UL / baud;
  Serial.print(F("Speed: "));
  Serial.print(baud);
  Serial.print(F(" baud = "));
  Serial.print(bitUs / 1000.0, 1);
  Serial.println(F(" ms per bit"));
}

void readKeyboard() {
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\r') continue;
    if (c == '\n') {
      lineBuf[lineLen] = 0;
      if (lineBuf[0] == '#') {
        setBaud(atoi(lineBuf + 1));
      } else {
        Serial.print(F("TX> "));
        Serial.println(lineBuf);
        Serial.print(F("RX< "));
        for (byte i = 0; i < lineLen; i++) enqueue(lineBuf[i]);
        enqueue('\n');
      }
      lineLen = 0;
    } else if (lineLen < sizeof(lineBuf) - 1) {
      lineBuf[lineLen++] = c;
    }
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(TX_PIN, OUTPUT);
  calibrate();
  digitalWrite(TX_PIN, HIGH);  // idle = light
  setBaud(baud);
  Serial.println(F("Type a message and press Enter. '#20' = 20 baud."));
}

void loop() {
  readKeyboard();
  serviceTx();
  serviceRx();
}

// Arduino Bench — Unit 11: LCD1602 dashboard with custom-character bar graph
//
// LCD (HD44780, 4-bit mode)
//   1 VSS -> GND        2 VDD -> 5V        3 V0 -> 10k contrast pot wiper
//   4 RS  -> D12        5 RW  -> GND       6 E  -> D11
//   11 D4 -> D5   12 D5 -> D4   13 D6 -> D3   14 D7 -> D2
//   15 A (backlight +) -> 220 ohm -> 5V    16 K -> GND
// A second pot (or any 0-5 V signal) on A0 is what gets displayed.

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);  // RS, E, D4, D5, D6, D7

// Each LCD character is a 5x8 pixel grid. These define 1..5 filled columns.
byte bar1[8] = {0x10,0x10,0x10,0x10,0x10,0x10,0x10,0x10};
byte bar2[8] = {0x18,0x18,0x18,0x18,0x18,0x18,0x18,0x18};
byte bar3[8] = {0x1C,0x1C,0x1C,0x1C,0x1C,0x1C,0x1C,0x1C};
byte bar4[8] = {0x1E,0x1E,0x1E,0x1E,0x1E,0x1E,0x1E,0x1E};
byte bar5[8] = {0x1F,0x1F,0x1F,0x1F,0x1F,0x1F,0x1F,0x1F};

void setup() {
  lcd.begin(16, 2);
  lcd.createChar(1, bar1);  // custom chars live in the LCD's CGRAM (8 slots)
  lcd.createChar(2, bar2);
  lcd.createChar(3, bar3);
  lcd.createChar(4, bar4);
  lcd.createChar(5, bar5);
  lcd.clear();
}

void loop() {
  int raw = analogRead(A0);
  float v = raw * 5.0 / 1024.0;

  lcd.setCursor(0, 0);
  lcd.print(F("A0 "));
  lcd.print(v, 2);
  lcd.print(F("V  "));
  lcd.setCursor(10, 0);
  unsigned long s = millis() / 1000;
  lcd.print(s / 60);
  lcd.print(':');
  if (s % 60 < 10) lcd.print('0');
  lcd.print(s % 60);
  lcd.print(F("  "));

  // 16 cells x 5 columns = 80 levels of resolution
  int columns = map(raw, 0, 1023, 0, 80);
  lcd.setCursor(0, 1);
  for (byte cell = 0; cell < 16; cell++) {
    int fill = columns - cell * 5;
    if (fill >= 5) lcd.write(byte(5));
    else if (fill > 0) lcd.write(byte(fill));
    else lcd.write(' ');
  }
  delay(100);
}

// Arduino Bench — Unit 12: Where does the current go? (sleep modes)
//
// Power the Uno from a 9 V battery into VIN with the multimeter (mA range)
// IN SERIES with the battery's + lead. USB unplugged!
// Button between D2 and GND. Each press moves to the next mode:
//
//   Mode 0  BUSY      CPU spinning in loop()  (delay() is also busy!)
//   Mode 1  BUSY+LED  on-board LED on - how much does one LED add?
//   Mode 2  IDLE      CPU clock stopped, timers still run (wakes every 1 ms)
//   Mode 3  POWER-DOWN almost everything off; only a LOW on D2 wakes it up
//
// The on-board LED blinks (mode+1) times to tell you which mode you're in.

#include <avr/sleep.h>

const byte BUTTON_PIN = 2;
byte mode = 0;

void wakeUp() {
  detachInterrupt(digitalPinToInterrupt(BUTTON_PIN));  // LOW level would fire forever
}

bool buttonPressed() {
  if (digitalRead(BUTTON_PIN) == HIGH) return false;
  delay(30);                                   // debounce
  if (digitalRead(BUTTON_PIN) == HIGH) return false;
  while (digitalRead(BUTTON_PIN) == LOW) {}    // wait for release
  delay(30);
  return true;
}

void announce() {
  for (byte i = 0; i <= mode; i++) {
    digitalWrite(LED_BUILTIN, HIGH); delay(150);
    digitalWrite(LED_BUILTIN, LOW);  delay(250);
  }
  if (mode == 1) digitalWrite(LED_BUILTIN, HIGH);
}

void powerDown() {
  digitalWrite(LED_BUILTIN, LOW);
  byte oldAdcsra = ADCSRA;
  ADCSRA = 0;                                 // ADC off (saves ~100s of uA on a bare chip)
  set_sleep_mode(SLEEP_MODE_PWR_DOWN);
  noInterrupts();
  sleep_enable();
  EIFR = bit(INTF0);                          // clear any stale INT0 flag
  // In power-down only a LOW LEVEL on INT0/INT1 can wake the chip
  // (edge detection needs the I/O clock, which is stopped)
  attachInterrupt(digitalPinToInterrupt(BUTTON_PIN), wakeUp, LOW);
  interrupts();
  sleep_cpu();                                // ...zzz... execution stops here
  sleep_disable();                            // ...and continues here after wake-up
  ADCSRA = oldAdcsra;
  while (digitalRead(BUTTON_PIN) == LOW) {}   // the waking press: wait for release
  delay(30);
}

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  announce();
}

void loop() {
  if (buttonPressed()) {
    mode = (mode + 1) % 4;
    digitalWrite(LED_BUILTIN, LOW);
    announce();
  }

  switch (mode) {
    case 0:
    case 1:
      // busy: nothing to do, the CPU just spins round and round
      break;
    case 2:
      set_sleep_mode(SLEEP_MODE_IDLE);
      sleep_mode();                           // sleeps until the next interrupt (~1 ms)
      break;
    case 3:
      powerDown();
      mode = 0;                               // woken up -> back to mode 0
      announce();
      break;
  }
}

// Arduino Bench — Capstone 1: The Bench Meter
// A 4-mode instrument on an LCD1602: Volts, Ohms (+continuity beep),
// Capacitance and Frequency. Every mode is a circuit you built earlier.
//
// LCD:  RS->D12, E->D11, D4->D4, D5->D5, D6->D6, D7->D7  (RW->GND, V0->pot)
// Mode button: D3 -> GND
// VOLT : probe+ --[30k (3x10k)]--+-- A0 --[10k]-- GND     (max 20 V, DC, positive only!)
// OHM  : 5V --[10k ref]--+-- A2 -- probe ... Rx ... -- GND
// CAP  : D8 --[10k]--+-- A1 ;  D9 --[220]--+ ;  capacitor between A1 node and GND
// FREQ : signal (0..5 V) -> D2
// Buzzer (passive): D10 -> buzzer -> GND

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 4, 5, 6, 7);

const byte MODE_BTN = 3;
const byte FREQ_PIN = 2;
const byte CHARGE_PIN = 8;
const byte DISCHARGE_PIN = 9;
const byte BUZZER_PIN = 10;

// ---- calibration: measure your parts and enter the real values ----
const float DIVIDER_RATIO = 4.0;     // (R_top + R_bottom) / R_bottom
const float R_REF = 10000.0;         // ohmmeter reference resistor
const float R_CHARGE = 10000.0;      // capacitance charge resistor
long BANDGAP_mV = 1100;              // from your Unit 1 calibration

enum Mode { VOLT, OHM, CAP, FREQ, MODE_COUNT };
Mode mode = VOLT;
const char* const MODE_NAMES[] = {"VOLTS  (A0)", "OHMS   (A2)", "CAP    (A1)", "FREQ   (D2)"};

volatile unsigned long edges = 0;
void onRise() { edges++; }

long readVcc_mV() {
  ADMUX = _BV(REFS0) | _BV(MUX3) | _BV(MUX2) | _BV(MUX1);
  delay(2);
  ADCSRA |= _BV(ADSC);
  while (bit_is_set(ADCSRA, ADSC)) {}
  return (BANDGAP_mV * 1024L) / ADC;
}

int readAvg(byte pin) {
  analogRead(pin);
  long s = 0;
  for (byte i = 0; i < 16; i++) s += analogRead(pin);
  return s / 16;
}

void showValue(float value, byte decimals, const __FlashStringHelper* unit) {
  lcd.setCursor(0, 1);
  lcd.print(value, decimals);
  lcd.print(' ');
  lcd.print(unit);
  lcd.print(F("          "));
}

void showText(const __FlashStringHelper* text) {
  lcd.setCursor(0, 1);
  lcd.print(text);
  lcd.print(F("          "));
}

void measureVolts() {
  float vcc = readVcc_mV() / 1000.0;
  float v = readAvg(A0) * vcc / 1024.0 * DIVIDER_RATIO;
  showValue(v, 2, F("V"));
  delay(200);
}

void measureOhms() {
  int a = readAvg(A2);
  if (a >= 1015) { noTone(BUZZER_PIN); showText(F("OPEN")); delay(100); return; }
  float r = R_REF * a / (1024.0 - a);       // ratiometric: Vcc cancels
  if (r < 50) tone(BUZZER_PIN, 2000); else noTone(BUZZER_PIN);
  if (r >= 1000) showValue(r / 1000.0, 2, F("kOhm"));
  else showValue(r, 0, F("Ohm"));
  delay(100);
}

void measureCap() {
  digitalWrite(CHARGE_PIN, LOW);
  pinMode(DISCHARGE_PIN, OUTPUT);
  digitalWrite(DISCHARGE_PIN, LOW);
  unsigned long t0 = millis();
  while (analogRead(A1) > 1 && millis() - t0 < 5000) {}
  delay(50);
  pinMode(DISCHARGE_PIN, INPUT);

  unsigned long start = micros();
  digitalWrite(CHARGE_PIN, HIGH);
  bool timeout = false;
  while (analogRead(A1) < 647) {
    if (micros() - start > 5000000UL) { timeout = true; break; }
    if (digitalRead(MODE_BTN) == LOW) break;  // stay responsive
  }
  unsigned long tau = micros() - start;
  digitalWrite(CHARGE_PIN, LOW);

  float uF = tau / R_CHARGE;
  if (timeout) showText(F("> 500 uF / open"));
  else if (uF >= 1.0) showValue(uF, 2, F("uF"));
  else showValue(uF * 1000.0, 0, F("nF"));
  delay(300);
}

void measureFreq() {
  noInterrupts(); edges = 0; interrupts();
  attachInterrupt(digitalPinToInterrupt(FREQ_PIN), onRise, RISING);
  unsigned long t0 = millis();
  while (millis() - t0 < 1000) {
    if (digitalRead(MODE_BTN) == LOW) break;
  }
  detachInterrupt(digitalPinToInterrupt(FREQ_PIN));
  noInterrupts(); unsigned long n = edges; interrupts();

  if (n >= 100) {                      // fast: gate count, +-1 Hz is < 1 %
    showValue(n, 0, F("Hz (gate)"));
  } else {                             // slow: measure the period instead
    unsigned long hi = pulseIn(FREQ_PIN, HIGH, 2000000UL);
    unsigned long lo = pulseIn(FREQ_PIN, LOW, 2000000UL);
    if (hi && lo) showValue(1e6 / (hi + lo), 3, F("Hz (period)"));
    else showText(F("no signal"));
  }
}

void setMode(Mode m) {
  mode = m;
  noTone(BUZZER_PIN);
  lcd.clear();
  lcd.print(MODE_NAMES[mode]);
}

void setup() {
  lcd.begin(16, 2);
  pinMode(MODE_BTN, INPUT_PULLUP);
  pinMode(FREQ_PIN, INPUT);
  pinMode(CHARGE_PIN, OUTPUT);
  digitalWrite(CHARGE_PIN, LOW);
  pinMode(DISCHARGE_PIN, INPUT);
  lcd.print(F("Arduino Bench"));
  lcd.setCursor(0, 1);
  lcd.print(F("Bench Meter v1"));
  delay(1200);
  setMode(VOLT);
}

void loop() {
  if (digitalRead(MODE_BTN) == LOW) {
    delay(30);
    if (digitalRead(MODE_BTN) == LOW) {
      setMode((Mode)((mode + 1) % MODE_COUNT));
      while (digitalRead(MODE_BTN) == LOW) {}
      delay(30);
    }
  }

  switch (mode) {
    case VOLT: measureVolts(); break;
    case OHM:  measureOhms();  break;
    case CAP:  measureCap();   break;
    case FREQ: measureFreq();  break;
    default: break;
  }
}

// Arduino Bench — Capstone 2: Poor Man's Oscilloscope
//
// Probe: signal (0..5 V ONLY) --[1k]-- A0. Common ground.
// Built-in test signal: D5 outputs a square wave (tone()) - wire D5 -> 1k -> A0
// to test, or probe your 555, the RC filter, the LDR...
//
// The ADC normally runs at 125 kHz (prescaler 128) -> ~9.6 k samples/s.
// We drop the prescaler to 16 -> 1 MHz ADC clock -> roughly 50-60 k samples/s.
// The datasheet only promises full 10-bit accuracy up to 200 kHz, so we trade
// a few bits of precision for speed - a real engineering trade-off.
//
// Serial (115200), Serial Plotter for the trace. Commands:
//   + / -  slower / faster timebase       a  auto <-> normal trigger
//   t      cycle the test tone (off, 50, 200, 1000, 3000, 9000 Hz)
//   c      dump the next capture as CSV (time_us,volts) for a spreadsheet

const byte PROBE = A0;
const byte TEST_PIN = 5;
const int N = 400;
const float VCC = 5.0;

int samples[N];
const unsigned int TIMEBASES[] = {0, 20, 50, 100, 200, 500, 1000, 2000};  // extra us between samples
byte tb = 0;
bool autoTrigger = true;
bool csvNext = false;
int triggerLevel = 512;

const unsigned int TONES[] = {0, 50, 200, 1000, 3000, 9000};
byte toneIdx = 3;

void setFastAdc() {
  ADCSRA &= ~(bit(ADPS2) | bit(ADPS1) | bit(ADPS0));
  ADCSRA |= bit(ADPS2);  // ADPS = 100 -> prescaler 16 -> 16 MHz / 16 = 1 MHz
}

void applyTone() {
  if (TONES[toneIdx]) tone(TEST_PIN, TONES[toneIdx]);
  else noTone(TEST_PIN);
}

bool waitForTrigger() {
  // rising edge through triggerLevel: first be below, then go above
  unsigned long t0 = millis();
  while (analogRead(PROBE) >= triggerLevel - 8) { if (millis() - t0 > 100) return false; }
  while (analogRead(PROBE) < triggerLevel + 8)  { if (millis() - t0 > 100) return false; }
  return true;
}

void setup() {
  Serial.begin(115200);
  setFastAdc();
  applyTone();
}

void handleCommands() {
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '+' && tb < sizeof(TIMEBASES) / sizeof(TIMEBASES[0]) - 1) tb++;
    if (c == '-' && tb > 0) tb--;
    if (c == 'a') autoTrigger = !autoTrigger;
    if (c == 't') { toneIdx = (toneIdx + 1) % (sizeof(TONES) / sizeof(TONES[0])); applyTone(); }
    if (c == 'c') csvNext = true;
  }
}

void loop() {
  handleCommands();

  bool triggered = waitForTrigger();
  if (!triggered && !autoTrigger) return;   // normal mode: no trigger, no trace

  unsigned int extra = TIMEBASES[tb];
  unsigned long t0 = micros();
  for (int i = 0; i < N; i++) {
    samples[i] = analogRead(PROBE);
    if (extra) delayMicroseconds(extra);
  }
  float dtUs = (micros() - t0) / (float)N;   // real time per sample, measured

  // ---- measurements ----
  int lo = 1023, hi = 0;
  long sum = 0;
  for (int i = 0; i < N; i++) { lo = min(lo, samples[i]); hi = max(hi, samples[i]); sum += samples[i]; }
  int mid = (lo + hi) / 2, hyst = max(4, (hi - lo) / 10);
  int firstRise = -1, lastRise = -1, rises = 0, highCount = 0;
  bool above = samples[0] > mid;
  for (int i = 1; i < N; i++) {
    if (samples[i] > mid) highCount++;
    if (!above && samples[i] > mid + hyst) {
      above = true;
      if (firstRise < 0) firstRise = i;
      lastRise = i;
      rises++;
    } else if (above && samples[i] < mid - hyst) {
      above = false;
    }
  }

  // ---- output ----
  if (csvNext) {
    Serial.println(F("time_us,volts"));
    for (int i = 0; i < N; i++) {
      Serial.print(i * dtUs, 1);
      Serial.print(',');
      Serial.println(samples[i] * VCC / 1024.0, 3);
    }
    csvNext = false;
  } else {
    for (int i = 0; i < N; i++) {
      Serial.print(F("volts:"));
      Serial.println(samples[i] * VCC / 1024.0, 2);
    }
  }

  Serial.print(F("# fs="));
  Serial.print(1000.0 / dtUs, 1);
  Serial.print(F(" kS/s  window="));
  Serial.print(N * dtUs / 1000.0, 1);
  Serial.print(F(" ms  Vmin="));
  Serial.print(lo * VCC / 1024.0, 2);
  Serial.print(F(" Vmax="));
  Serial.print(hi * VCC / 1024.0, 2);
  Serial.print(F(" Vavg="));
  Serial.print(sum / (float)N * VCC / 1024.0, 2);
  if (rises >= 2) {
    float periodUs = (lastRise - firstRise) * dtUs / (rises - 1);
    Serial.print(F(" f="));
    Serial.print(1e6 / periodUs, 1);
    Serial.print(F(" Hz duty~"));
    Serial.print(100.0 * highCount / (N - 1), 0);
    Serial.print('%');
  }
  Serial.print(F(" test_tone="));
  Serial.print(TONES[toneIdx]);
  Serial.println(triggered ? F(" Hz [TRIG]") : F(" Hz [AUTO]"));
  delay(300);
}

